package studio.jiayu.neoagent;
import android.graphics.*;import org.json.*;
/** Numbered system annotations on already filtered pixels; no OCR or guessed button purposes. */
final class VisionGrounding {
 static String role(String klass,boolean editable,boolean scrollable){if(editable)return "输入框";if(klass.endsWith("Switch"))return "开关";if(klass.endsWith("CheckBox"))return "复选框";if(klass.endsWith("RadioButton"))return "单选按钮";if(klass.endsWith("Button"))return "按钮";if(scrollable)return "滚动区域";return "可点击区域";}
 static JSONArray controls(JSONArray filtered)throws Exception{JSONArray out=new JSONArray();for(int i=0;i<filtered.length();i++){JSONObject node=filtered.getJSONObject(i);if(!node.optBoolean("clickable")&&!node.optBoolean("editable")&&!node.optBoolean("scrollable")&&!node.optBoolean("runtime_actionable"))continue;JSONObject c=new JSONObject(node.toString());String label=c.optString("description").trim();if(label.isEmpty())label=c.optString("text").trim();c.put("purpose",label.isEmpty()?"系统未提供用途；依据画面确认":label).put("purpose_source",label.isEmpty()?"unknown":c.optString("description_source","android_accessibility"));out.put(c);}return out;}
 static void annotate(Bitmap image,JSONArray controls)throws Exception{Canvas canvas=new Canvas(image);Paint stroke=new Paint(3);stroke.setColor(Color.rgb(255,149,78));stroke.setStrokeWidth(Math.max(2,image.getWidth()/450f));stroke.setStyle(Paint.Style.STROKE);Paint fill=new Paint(3);fill.setColor(Color.rgb(36,30,26));Paint text=new Paint(3);text.setColor(Color.WHITE);text.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));text.setTextSize(Math.max(20,image.getWidth()/40f));
  for(int i=0;i<controls.length();i++){JSONObject n=controls.getJSONObject(i);JSONArray a=n.optJSONArray("bounds");if(a==null||a.length()!=4)continue;Rect r=new Rect(a.getInt(0)*image.getWidth()/1000,a.getInt(1)*image.getHeight()/1000,a.getInt(2)*image.getWidth()/1000,a.getInt(3)*image.getHeight()/1000);if(!r.intersect(0,0,image.getWidth(),image.getHeight())||r.isEmpty()||(long)r.width()*r.height()>(long)image.getWidth()*image.getHeight()*.35)continue;canvas.drawRect(r,stroke);String id="#"+n.getInt("id");float width=text.measureText(id)+12,height=text.getTextSize()+8,left=Math.min(r.left,image.getWidth()-width),top=Math.max(0,Math.min(r.top,image.getHeight()-height));canvas.drawRoundRect(left,top,left+width,top+height,5,5,fill);canvas.drawText(id,left+6,top+height-7,text);n.put("image_annotated",true);}
 }
}
